"use strict";

function validDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const date = new Date(Date.UTC(+match[1], +match[2] - 1, +match[3]));
  return date.getUTCFullYear() === +match[1] &&
    date.getUTCMonth() === +match[2] - 1 && date.getUTCDate() === +match[3];
}

function validateEntries(entries) {
  if (!Array.isArray(entries)) throw new TypeError("entries must be an array");
  const ids = new Set();
  for (const entry of entries) {
    if (entry === null || typeof entry !== "object" ||
        typeof entry.id !== "string" || entry.id.length === 0 || ids.has(entry.id) ||
        typeof entry.date !== "string" || !validDate(entry.date) ||
        typeof entry.time !== "string" || !/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(entry.time) ||
        typeof entry.text !== "string" || typeof entry.city !== "string" ||
        (entry.image !== null && typeof entry.image !== "string")) {
      throw new TypeError("invalid entry");
    }
    ids.add(entry.id);
  }
}

function clone(entry) {
  return { id: entry.id, date: entry.date, time: entry.time,
    text: entry.text, city: entry.city, image: entry.image };
}

function buildTimeline(entries, dateQuery) {
  validateEntries(entries);
  if (dateQuery !== null && (typeof dateQuery !== "string" || !validDate(dateQuery))) {
    throw new TypeError("invalid date query");
  }
  return entries
    .map((entry, index) => ({ entry, index }))
    .filter(({ entry }) => dateQuery === null || entry.date === dateQuery)
    .sort((a, b) => {
      const comparison = (a.entry.date + a.entry.time).localeCompare(b.entry.date + b.entry.time);
      return comparison || a.index - b.index;
    })
    .map(({ entry }) => clone(entry));
}

function deleteEntry(entries, id) {
  validateEntries(entries);
  if (typeof id !== "string") throw new TypeError("id must be a string");
  return entries.filter((entry) => entry.id !== id).map(clone);
}

function edgeIndex(entries, edge) {
  validateEntries(entries);
  if (edge !== "top" && edge !== "bottom") throw new TypeError("invalid edge");
  if (entries.length === 0) return -1;
  return edge === "top" ? 0 : entries.length - 1;
}

module.exports = { buildTimeline, deleteEntry, edgeIndex };

