"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api).sort(), ["buildTimeline", "deleteEntry", "edgeIndex"]);
const { buildTimeline, deleteEntry, edgeIndex } = api;

const entries = [
  { id: "a", date: "2024-02-29", time: "09:30", text: "first", city: "Pune", image: null },
  { id: "b", date: "2025-01-01", time: "00:00", text: "new year", city: "Delhi", image: "b.jpg" },
  { id: "c", date: "2024-02-29", time: "09:30", text: "second", city: "", image: "" },
  { id: "d", date: "2024-02-29", time: "23:59", text: "late", city: "Mumbai", image: null }
];
const snapshot = entries.map((entry) => ({ ...entry }));
const timeline = buildTimeline(entries, null);
assert.deepStrictEqual(timeline.map((entry) => entry.id), ["b", "d", "a", "c"]);
assert.deepStrictEqual(entries, snapshot);
for (const result of timeline) {
  assert.notStrictEqual(result, entries.find((entry) => entry.id === result.id));
}
timeline[0].text = "changed";
assert.strictEqual(entries[1].text, "new year");

const filtered = buildTimeline(entries, "2024-02-29");
assert.deepStrictEqual(filtered.map((entry) => entry.id), ["d", "a", "c"]);
assert.deepStrictEqual(buildTimeline([], null), []);

const deleted = deleteEntry(entries, "b");
assert.deepStrictEqual(deleted.map((entry) => entry.id), ["a", "c", "d"]);
assert.deepStrictEqual(entries, snapshot);
for (let i = 0; i < deleted.length; i += 1) {
  assert.notStrictEqual(deleted[i], entries.find((entry) => entry.id === deleted[i].id));
}
const absent = deleteEntry(entries, "missing");
assert.deepStrictEqual(absent, entries);
assert.notStrictEqual(absent, entries);
for (let i = 0; i < entries.length; i += 1) assert.notStrictEqual(absent[i], entries[i]);
assert.deepStrictEqual(deleteEntry(entries, ""), entries);

assert.strictEqual(edgeIndex([], "top"), -1);
assert.strictEqual(edgeIndex([], "bottom"), -1);
assert.strictEqual(edgeIndex(entries, "top"), 0);
assert.strictEqual(edgeIndex(entries, "bottom"), entries.length - 1);
assert.throws(() => edgeIndex(entries, "left"), TypeError);
assert.throws(() => edgeIndex(entries, null), TypeError);

const valid = entries[0];
const invalidEntries = [
  null,
  {},
  [null],
  [{ ...valid, id: "" }],
  [{ ...valid, id: 1 }],
  [{ ...valid, text: 1 }],
  [{ ...valid, city: null }],
  [{ ...valid, date: "2023-02-29" }],
  [{ ...valid, date: "2024-2-29" }],
  [{ ...valid, time: "24:00" }],
  [{ ...valid, time: "9:30" }],
  [{ ...valid, image: 3 }],
  [valid, { ...valid }]
];
for (const invalid of invalidEntries) {
  assert.throws(() => buildTimeline(invalid, null), TypeError);
  assert.throws(() => deleteEntry(invalid, "a"), TypeError);
  assert.throws(() => edgeIndex(invalid, "top"), TypeError);
}
for (const invalidDate of ["", "2025-02-29", "2025-13-01", "2025-01-32", 1, undefined]) {
  assert.throws(() => buildTimeline(entries, invalidDate), TypeError);
}
for (const invalidId of [null, 1, {}, []]) {
  assert.throws(() => deleteEntry(entries, invalidId), TypeError);
}

